namespace Framework.Save
{
    /// <summary>
    /// データ保存システムの共通インターフェース。
    ///
    /// 保存方式や外部アセットに依存せず、
    /// データの保存・読み込み・削除を行うための
    /// 共通仕様を定義する。
    ///
    /// 実際の保存処理は、このインターフェースを
    /// 実装した各Providerが担当する。
    /// </summary>
    public interface ISaveProvider
    {
        #region Save Methods

        /// <summary>
        /// 指定されたキーにデータを保存する。
        ///
        /// 同じキーのデータが存在する場合は
        /// 既存のデータを上書きする。
        ///
        /// 保存に失敗した場合は例外を発生させる。
        /// </summary>
        /// <typeparam name="T">
        /// 保存するデータの型
        /// </typeparam>
        /// <param name="key">
        /// データを識別するキー
        /// </param>
        /// <param name="value">
        /// 保存するデータ
        /// </param>
        void Save<T>(string key, T value);

        #endregion

        #region Load Methods

        /// <summary>
        /// 指定されたキーのデータを読み込む。
        ///
        /// データが存在しない場合は
        /// 指定された初期値を返す。
        ///
        /// データの破損や型の不一致などにより
        /// 読み込みに失敗した場合は例外を発生させる。
        /// </summary>
        /// <typeparam name="T">
        /// 読み込むデータの型
        /// </typeparam>
        /// <param name="key">
        /// データを識別するキー
        /// </param>
        /// <param name="defaultValue">
        /// データが存在しない場合に返す初期値
        /// </param>
        /// <returns>
        /// 読み込んだデータ、または指定された初期値
        /// </returns>
        T Load<T>(string key, T defaultValue);

        /// <summary>
        /// 指定されたキーのデータの読み込みを試みる。
        ///
        /// データが存在しない場合や、
        /// 保存データの読み込みに失敗した場合は
        /// falseを返す。
        /// </summary>
        /// <typeparam name="T">
        /// 読み込むデータの型
        /// </typeparam>
        /// <param name="key">
        /// データを識別するキー
        /// </param>
        /// <param name="value">
        /// 読み込んだデータ。
        /// 失敗した場合は型の既定値。
        /// </param>
        /// <returns>
        /// 読み込みに成功した場合はtrue
        /// </returns>
        bool TryLoad<T>(string key, out T value);

        #endregion

        #region Data Management Methods

        /// <summary>
        /// 指定されたキーの保存データが存在するか
        /// 確認する。
        /// </summary>
        /// <param name="key">
        /// 確認するデータのキー
        /// </param>
        /// <returns>
        /// データが存在する場合はtrue
        /// </returns>
        bool Exists(string key);

        /// <summary>
        /// 指定されたキーの保存データを削除する。
        ///
        /// データが存在しない場合は何も行わない。
        /// </summary>
        /// <param name="key">
        /// 削除するデータのキー
        /// </param>
        void Delete(string key);

        /// <summary>
        /// このProviderが管理するすべての
        /// 保存データを削除する。
        ///
        /// 他のProviderが管理する保存領域には
        /// 影響を与えないことを前提とする。
        /// </summary>
        void DeleteAll();

        /// <summary>
        /// 保留中の保存処理を確定する。
        ///
        /// キャッシュ方式などを採用している場合は、
        /// 保留中のデータを実際の保存先へ書き込む。
        ///
        /// 即時保存方式の場合は何も行わない。
        /// </summary>
        void Flush();

        #endregion
    }
}
